var sb = new System.Text.StringBuilder(); foreach (var c in UnityEngine.Object.FindObjectsByType<Protobot.Motion.ChainLoop>(UnityEngine.FindObjectsSortMode.None)) { var b = new UnityEngine.Bounds(c.transform.position, UnityEngine.Vector3.zero); foreach (var r in c.GetComponentsInChildren<UnityEngine.Renderer>()) b.Encapsulate(r.bounds); sb.Append(b.center.ToString("F0") + " size " + b.size.ToString("F0") + " | "); } return sb.ToString();
